import type { BankQuestion } from "@/lib/bank";

/** Morphology and Anatomy of Flowering Plants (Biology (NEET)): 133 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-plant-morphology-anatomy-1","question":"Prop roots that arise from branches and grow down into the soil to support a large tree are seen in:","options":["Sweet potato","Maize","Rhizophora","Banyan"],"answer":3,"explanation":"The hanging structures supporting a banyan tree are prop roots. Maize and sugarcane have stilt roots from lower nodes, and Rhizophora has pneumatophores.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-2","question":"In pea, the tendrils that help the plant climb are modifications of:","options":["Adventitious roots","Leaflets","Stipules","Axillary buds"],"answer":1,"explanation":"In pea the terminal leaflets of the compound leaf are modified into tendrils. Tendrils of cucumber and grapevine are stem tendrils arising from buds.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-3","question":"The pattern of arrangement of ovules within the ovary is called:","options":["Placentation","Phyllotaxy","Aestivation","Inflorescence"],"answer":0,"explanation":"Placentation is the arrangement of ovules in the ovary; aestivation is the arrangement of sepals or petals in a bud, and phyllotaxy that of leaves on the stem.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-4","question":"Pneumatophores, roots that come out of the ground and grow vertically upwards to get oxygen for respiration, are found in:","options":["Monstera","Banyan tree","Turnip","Rhizophora"],"answer":3,"explanation":"Mangrove plants like Rhizophora grow in swampy, oxygen-poor soil; their pneumatophores grow upwards to obtain oxygen.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-5","question":"Free central placentation, in which ovules are borne on the central axis and septa are absent, is seen in:","options":["Pea","Mustard","Dianthus","China rose"],"answer":2,"explanation":"Dianthus and Primrose show free central placentation. Pea is marginal, mustard parietal and china rose axile.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-6","question":"Stamens attached to the perianth (epiphyllous stamens) are seen in the flower of:","options":["Mustard","Lily","Brinjal","Pea"],"answer":1,"explanation":"Stamens attached to the perianth are epiphyllous, as in lily; stamens attached to petals are epipetalous, as in brinjal.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-7","question":"Tendrils of cucumber, pumpkin and watermelon develop from:","options":["Leaflets","Adventitious roots","Axillary buds","Stipules"],"answer":2,"explanation":"Stem tendrils of cucumbers, pumpkins, watermelon and grapevines develop from axillary buds; axillary buds also form thorns in Citrus and Bougainvillea.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-8","question":"The Casparian strips present on the radial and inner tangential walls of the endodermal cells of roots are made of:","options":["Hemicellulose","Suberin","Cutin","Lignin"],"answer":1,"explanation":"The tangential and radial walls of endodermal cells bear a deposit of water-impermeable, waxy suberin in the form of Casparian strips.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-9","question":"In a temperate tree, autumn wood (late wood) differs from spring wood (early wood) in that autumn wood:","options":["Is darker and denser, with fewer and narrower xylary elements","Is formed by the cork cambium, not the vascular cambium","Has more vessels, with wider cavities, for rapid conduction","Is lighter in colour and lower in density, with thin walls"],"answer":0,"explanation":"In winter the cambium is less active and forms fewer, narrower xylary elements, so autumn wood is darker and denser; spring wood has many vessels with wide cavities and is lighter. Together they form an annual ring.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-10","question":"A family has the floral formula ⊕ ⚥ K(5) C(5) A5 G(2), with a bicarpellary syncarpous superior ovary, swollen placenta and obliquely placed carpels. This family is:","options":["Liliaceae","Fabaceae","Solanaceae","Brassicaceae"],"answer":2,"explanation":"These are the floral features of Solanaceae (potato family), e.g., Solanum nigrum. Fabaceae has a monocarpellary ovary and Liliaceae a tricarpellary ovary.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-11","question":"Diadelphous stamens (9) + 1 and a monocarpellary superior ovary with marginal placentation are features of:","options":["Solanaceae","Liliaceae","Malvaceae","Fabaceae"],"answer":3,"explanation":"In Fabaceae (Papilionoideae) the ten stamens are diadelphous and the ovary is monocarpellary, unilocular with many ovules on marginal placentation.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-12","question":"The floral formula Br ⊕ ⚥ P(3+3) A3+3 G(3) represents the family:","options":["Liliaceae","Fabaceae","Solanaceae","Poaceae"],"answer":0,"explanation":"Liliaceae has a bracteate, actinomorphic, bisexual flower with six tepals in two whorls, six stamens and a tricarpellary syncarpous superior trilocular ovary with axile placentation.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-13","question":"A transverse section of a root shows more than six xylem bundles (polyarch) and a large, well-developed pith. The root is:","options":["A monocot root","A dicot root","A dicot root after secondary growth","A gymnosperm root"],"answer":0,"explanation":"Dicot roots usually have two to four xylem and phloem patches and little or no pith. Monocot roots have more than six (polyarch) xylem bundles and a large pith, and do not undergo secondary growth.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-14","question":"Vascular bundles in which cambium is present between xylem and phloem are called open. Such conjoint open bundles are typical of:","options":["Dicot stems","Monocot stems","Dicot roots","Monocot leaves"],"answer":0,"explanation":"Dicot stems have conjoint, open vascular bundles that can form secondary tissues. Monocot stems have closed bundles (no cambium), and roots have radial bundles.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-15","question":"Phloem parenchyma is absent and water-containing cavities are present within the vascular bundles of:","options":["The monocot root","The dicot stem","The dicot leaf","The monocot stem"],"answer":3,"explanation":"In the monocot stem the scattered vascular bundles are conjoint, closed and surrounded by a sclerenchymatous bundle sheath; phloem parenchyma is absent and water-containing cavities are present.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-16","question":"In grasses, bulliform cells help to roll the leaf. Which statement about them is correct?","options":["They are sclerenchymatous cells that keep the leaf permanently rolled","They are chloroplast-rich palisade cells that store water for drought","Large, empty, colourless adaxial cells; when flaccid the leaf curls inwards","They are present on the abaxial epidermis and open stomata when turgid"],"answer":2,"explanation":"Some adaxial epidermal cells along the veins of grass leaves become large, empty and colourless bulliform cells. When turgid the leaf surface is exposed; when flaccid (water stress) the leaf curls inwards to minimise water loss.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-17","question":"The term 'bark' refers to:","options":["All tissues outside the vascular cambium, with secondary phloem","Only the dead tissues that lie outside the active cork cambium","Only the cork (phellem), the outermost dead layer","Only the periderm: phellem, phellogen and phelloderm together"],"answer":0,"explanation":"Bark is a non-technical term for all tissues exterior to the vascular cambium, including secondary phloem. Phellem, phellogen and phelloderm together are the periderm.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-18","question":"In a dicot stem, the interfascicular cambium arises from:","options":["The pericycle cells lying opposite the protoxylem","The endodermis, i.e. the starch sheath","The epidermis, by dedifferentiation of its cells","Medullary ray cells beside the intrafascicular cambium"],"answer":3,"explanation":"Cells of the medullary rays next to the intrafascicular (fascicular) cambium become meristematic to form the interfascicular cambium, completing a continuous ring of cambium.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-19","question":"How many of the following pairs of plant and modified organ are correct?\n(i) Sweet potato: adventitious root modified for food storage\n(ii) Potato: stem tuber\n(iii) Ginger: underground stem (rhizome)\n(iv) Opuntia: stem modified into a flattened green photosynthetic structure","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four pairs are correct: sweet potato has storage adventitious roots, potato is a stem tuber, ginger is a rhizome, and in Opuntia the stem forms a flattened green phylloclade while the leaves are reduced to spines.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-20","question":"Match the type of placentation with the plant.\nList I: (A) Marginal (B) Axile (C) Parietal (D) Basal\nList II: (1) Sunflower and marigold (2) Mustard and Argemone (3) China rose, tomato and lemon (4) Pea","options":["A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1"],"answer":0,"explanation":"Pea has marginal placentation; china rose, tomato and lemon axile; mustard and Argemone parietal; sunflower and marigold basal, with a single ovule at the base.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-21","question":"Assertion (A): Sapwood conducts water and minerals, whereas heartwood does not.\nReason (R): The cells of heartwood are dead and are filled with tannins, resins, oils, gums and aromatic substances.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: deposition of these organic compounds makes heartwood hard, durable and dark, and its dead, filled elements cannot conduct water, though they still give mechanical support.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-22","question":"How many of the following statements about the anatomy of a dicot stem are correct?\n(i) The hypodermis consists of a few layers of collenchymatous cells.\n(ii) The innermost layer of the cortex is rich in starch grains and is called the starch sheath.\n(iii) The vascular bundles are arranged in a ring.\n(iv) The protoxylem lies towards the centre (endarch).","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: the dicot stem has a collenchymatous hypodermis, a starch sheath as the innermost cortex layer, vascular bundles in a ring, and endarch protoxylem (exarch is a root feature).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-23","question":"Which plant is wrongly matched with its family?","options":["Petunia: Solanaceae","Ashwagandha: Fabaceae","Colchicine source: Liliaceae","Muliathi: Fabaceae"],"answer":1,"explanation":"Ashwagandha (Withania) is a medicinal plant of Solanaceae. Muliathi (liquorice) is a fabaceous medicine, colchicine comes from Colchicum autumnale of Liliaceae, and Petunia is an ornamental solanaceous plant.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-24","question":"How many of the following statements are correct?\n(i) In hypogynous flowers the ovary is superior, as in mustard, china rose and brinjal.\n(ii) Plum, rose and peach have perigynous flowers.\n(iii) Guava, cucumber and the ray florets of sunflower have epigynous flowers.\n(iv) The flower of Canna is asymmetric, as it cannot be divided into two similar halves by any vertical plane.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. In perigynous flowers the ovary is half-inferior; in epigynous flowers the ovary is inferior.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-25","question":"Match the aestivation with its example.\nList I: (A) Valvate (B) Twisted (C) Imbricate (D) Vexillary\nList II: (1) Cassia and gulmohur (2) Calotropis (3) Pea and bean (4) China rose, lady's finger and cotton","options":["A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3"],"answer":1,"explanation":"Calotropis is valvate (margins just touch); china rose, lady's finger and cotton are twisted; Cassia and gulmohur are imbricate (no particular direction); pea and bean are vexillary (papilionaceous).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-26","question":"Assertion (A): In dicot roots the vascular cambium is completely secondary in origin.\nReason (R): It is formed entirely from the endodermis.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true but R is false: the root cambium originates from tissue just below the phloem bundles and a portion of the pericycle above the protoxylem, forming a wavy ring that later becomes circular.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-27","question":"How many of the following statements about root anatomy are correct?\n(i) The endodermal cells bear Casparian strips of suberin.\n(ii) Lateral roots arise from the endodermis.\n(iii) Parenchymatous cells lying between the xylem and phloem are called conjunctive tissue.\n(iv) Monocot roots undergo extensive secondary growth.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (iii) are correct. Lateral roots and, in dicots, part of the vascular cambium arise from the pericycle, and monocot roots do not undergo secondary growth.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-28","question":"How many of the following statements about leaf anatomy are correct?\n(i) In a dorsiventral leaf, the mesophyll is differentiated into palisade and spongy parenchyma.\n(ii) In a dorsiventral leaf, the abaxial epidermis generally bears more stomata than the adaxial epidermis.\n(iii) In an isobilateral leaf, the mesophyll is not differentiated into palisade and spongy parenchyma.\n(iv) The vascular bundles of the leaf are surrounded by a layer of thick-walled bundle sheath cells.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. An isobilateral (monocot) leaf has stomata on both surfaces and veins of almost equal size because of parallel venation.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-29","question":"In which option are all three underground or modified structures stems?","options":["Sweet potato, ginger and Opuntia","Pistia, turnip and Eichhornia","Ginger, Colocasia and potato","Carrot, zaminkand and potato"],"answer":2,"explanation":"Ginger (rhizome), Colocasia (corm) and potato (tuber) are all stems. Sweet potato, carrot and turnip are roots, while Opuntia, zaminkand, Pistia and Eichhornia are stems, so the other options each contain a root.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-30","question":"How many of the following statements about vascular tissues are correct?\n(i) Gymnosperms lack vessels in their xylem.\n(ii) Gymnosperms have albuminous cells and sieve cells, and lack sieve tubes and companion cells.\n(iii) Phloem fibres are generally absent in the primary phloem but are found in the secondary phloem.\n(iv) Xylem parenchyma stores food as starch or fat, and ray parenchyma cells carry out radial conduction of water.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct NCERT statements on xylem and phloem. Vessels are a characteristic feature of angiosperms.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-31", "question": "Whorled phyllotaxy, in which more than two leaves arise at a node and form a whorl, is seen in:", "options": ["Alstonia", "Guava", "China rose", "Mustard"], "answer": 0, "explanation": "Alstonia has whorled phyllotaxy. China rose and mustard have alternate leaves, and guava and Calotropis have opposite leaves.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-32", "question": "A fleshy fruit that develops from a monocarpellary superior ovary and has a stony endocarp, as in mango and coconut, is called a:", "options": ["Berry", "Drupe", "Legume", "Capsule"], "answer": 1, "explanation": "Mango and coconut are drupes. In mango the mesocarp is fleshy and edible; in coconut it is fibrous.", "difficulty": "easy", "source": "NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-33","question":"Parallel venation is generally characteristic of:","options":["Dicotyledons","Gymnosperms like Pinus","Monocotyledons","Pteridophytes"],"answer":2,"explanation":"Most monocots have parallel venation, while dicots generally have reticulate venation.","difficulty":"easy","source":"NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-34", "question": "The fibrous part of the coconut fruit, used for coir, is the:", "options": ["Epicarp", "Endosperm", "Endocarp", "Mesocarp"], "answer": 3, "explanation": "The coconut is a drupe with a fibrous mesocarp; the endocarp is the hard stony shell and the edible part is the endosperm.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-35","question":"In aquatic plants such as Pistia and Eichhornia, a lateral branch with short internodes, each node bearing a rosette of leaves and a tuft of roots, is called:","options":["An offset","A rhizome","A runner","A stolon"],"answer":0,"explanation":"Offsets of Pistia and Eichhornia are one-internode-long lateral branches that help in vegetative propagation. Runners occur in grasses and strawberry, and suckers in banana, pineapple and Chrysanthemum.","difficulty":"moderate","source":"NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-36", "question": "The spines of cacti are modifications of:", "options": ["Stems", "Leaves", "Roots", "Axillary buds"], "answer": 1, "explanation": "Cactus spines are modified leaves that reduce water loss; the green fleshy body is the stem. Thorns of Citrus and Bougainvillea, by contrast, are modified axillary buds.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-37", "question": "Neem and silk cotton have compound leaves that are, respectively:", "options": ["Palmately compound and pinnately compound", "Pinnately compound and palmately compound", "Both pinnately compound", "Both palmately compound"], "answer": 1, "explanation": "Neem has a pinnately compound leaf with leaflets along the rachis; silk cotton has a palmately compound leaf with leaflets attached at the tip of the petiole.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-38", "question": "In a grass (monocot) seed, the single large, shield-shaped cotyledon is called the:", "options": ["Coleoptile", "Coleorhiza", "Scutellum", "Aleurone layer"], "answer": 2, "explanation": "The cotyledon of the grass embryo is the scutellum. The coleoptile and coleorhiza are sheaths over the plumule and radicle, and the aleurone layer is the protein-rich outer layer of the endosperm.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-39","question":"Intercalary meristems, which help grasses regenerate parts removed by grazing herbivores, are located:","options":["At the tips of roots, behind the root cap","At the tips of shoots","In the cork cambium of the stem","At the bases of leaves or internodes"],"answer":3,"explanation":"Intercalary meristems occur at the base of leaves or internodes in grasses; like apical meristems they are primary meristems.","difficulty":"moderate","source":"NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-40", "question": "In angiosperm phloem, the functions of the enucleate sieve tube elements are controlled by:", "options": ["The nucleus of the companion cells", "The nucleus of the phloem parenchyma", "The nuclei of phloem fibres", "Their own nucleus, which persists"], "answer": 0, "explanation": "A mature sieve tube element has peripheral cytoplasm and a large vacuole but no nucleus; the nucleus of the associated companion cell, linked through pit fields, controls it.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-41", "question": "The arrangement of primary xylem in roots, with the protoxylem lying towards the periphery and the metaxylem towards the centre, is called:", "options": ["Endarch", "Exarch", "Mesarch", "Conjoint"], "answer": 1, "explanation": "Roots have exarch xylem. Stems have endarch xylem, with the protoxylem towards the centre (pith).", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-42","question":"The thickening at the corners of collenchyma cells is due to the deposition of:","options":["Lignin and suberin, as in sclerenchyma","Cutin and wax","Cellulose, hemicellulose and pectin","Callose and lignin"],"answer":2,"explanation":"Collenchyma walls are thickened at the corners with cellulose, hemicellulose and pectin, giving mechanical support to young stems and petioles while staying flexible.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-43", "question": "Vascular bundles in which xylem and phloem lie on alternate radii are called radial bundles. They are found in:", "options": ["Dicot stems", "Monocot stems", "Leaves", "Roots"], "answer": 3, "explanation": "Radial vascular bundles are typical of roots. Stems and leaves have conjoint bundles, with xylem and phloem on the same radius.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-44", "question": "Which plant of the family Fabaceae is a source of fibre?", "options": ["Crotalaria juncea (sunn hemp)", "Trifolium", "Indigofera", "Glycyrrhiza glabra (muliathi)"], "answer": 0, "explanation": "Sunn hemp yields fibre. Indigofera gives a dye, Trifolium and Sesbania are fodder, and muliathi is medicinal.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-45","question":"Lenticels, the lens-shaped openings that permit exchange of gases between the outer atmosphere and the internal tissue of the stem, are formed because the phellogen:","options":["Produces suberised cork cells uniformly all around the stem","Cuts off parenchyma, not cork cells, outwards at certain places","Dies at certain places, leaving gaps in the bark","Produces secondary xylem on its outer side at those places"],"answer":1,"explanation":"At certain points the phellogen forms loose parenchyma instead of cork; these cells rupture the epidermis to form lenticels. They occur in most woody trees.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-46", "question": "The periderm of a woody stem consists of:", "options": ["Epidermis, cortex and pericycle", "Secondary xylem, cambium and secondary phloem", "Phellem, phellogen and phelloderm", "Cork and secondary phloem only"], "answer": 2, "explanation": "Phellogen (cork cambium), phellem (cork) and phelloderm (secondary cortex) together form the periderm. Bark is a broader term for all tissues outside the vascular cambium.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-47","question":"In a racemose inflorescence:","options":["The main axis ends in a flower and flowers open in basipetal order","All flowers arise from one point on a flattened receptacle and open together","There is a single terminal flower on the axis","The main axis keeps growing and lateral flowers arise acropetally"],"answer":3,"explanation":"In racemose inflorescences the main axis keeps growing and the flowers are borne laterally in acropetal order. In cymose inflorescences the axis ends in a flower and flowers open basipetally.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-48", "question": "Root hairs arise from the epidermal cells of the:", "options": ["Region of maturation", "Region of meristematic activity", "Region of elongation", "Root cap"], "answer": 0, "explanation": "Cells of the elongation zone gradually differentiate in the region of maturation, and some epidermal cells there form root hairs that absorb water and minerals.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-49", "question": "How many of the following statements about the family Liliaceae are correct?\n(i) The perianth consists of six tepals, often united into a tube.\n(ii) The fruit is a legume.\n(iii) There are six stamens in two whorls (3 + 3), and they are epitepalous.\n(iv) The ovary is inferior and bilocular.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only (i) and (iii) are correct. The fruit of Liliaceae is a capsule, rarely a berry, and the tricarpellary ovary is superior and trilocular with axile placentation.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-50", "question": "Match the tissue with its description.\nList I: (A) Tracheids (B) Companion cells (C) Phloem fibres (D) Xylem parenchyma\nList II: (1) Store food as starch or fat, and substances like tannins (2) Elongated, dead cells with thick lignified walls and tapering ends (3) Sclerenchymatous cells generally absent in primary phloem (4) Specialised parenchymatous cells closely associated with sieve tube elements", "options": ["A-4, B-2, C-3, D-1", "A-2, B-4, C-3, D-1", "A-2, B-3, C-4, D-1", "A-2, B-4, C-1, D-3"], "answer": 1, "explanation": "Tracheids are dead, lignified and tapering; companion cells serve sieve tubes; phloem fibres (bast) are sclerenchyma found in secondary phloem; xylem parenchyma stores food and tannins.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-51", "question": "Assertion (A): Most monocot stems do not show secondary growth.\nReason (R): The vascular bundles of monocot stems are closed, lacking cambium.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Secondary growth needs a vascular cambium; the scattered, closed bundles of monocot stems lack it, so they generally do not grow in thickness by secondary growth.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-52","question":"How many of the following statements about secondary growth in a dicot stem are correct?\n(i) The vascular cambium is more active on the inner side, so more secondary xylem than secondary phloem is formed.\n(ii) The primary and secondary phloem gradually get crushed due to continued formation of secondary xylem.\n(iii) The cambium forms narrow bands of parenchyma, the secondary medullary rays, that pass radially through the secondary xylem and phloem.\n(iv) The outer cells cut off by the phellogen differentiate into phelloderm.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. The phellogen's outer derivatives become phellem (cork) and its inner derivatives become phelloderm (secondary cortex).","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-53", "question": "All of the following are modifications of the leaf or its parts EXCEPT:", "options": ["Tendrils of pea", "Phyllodes of Australian Acacia", "Thorns of Bougainvillea", "Fleshy storage leaves of onion"], "answer": 2, "explanation": "Bougainvillea thorns are modified axillary buds, i.e. stem structures. Pea tendrils are modified leaflets, the expanded green petioles of Australian Acacia are leaf parts, and onion bulb scales are fleshy leaves.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-54", "question": "How many of the following statements about flowers are correct?\n(i) A bracteate flower has a reduced leaf at the base of the pedicel.\n(ii) The flower of Cassia is actinomorphic.\n(iii) In lotus and rose, the carpels are free (apocarpous).\n(iv) Polyadelphous stamens are found in pea.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only (i) and (iii) are correct. Cassia, pea, bean and gulmohur have zygomorphic flowers, and pea has diadelphous stamens; polyadelphous stamens occur in Citrus.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-55", "question": "Match the structure with its feature.\nList I: (A) Hypodermis of a monocot stem (B) Hypodermis of a dicot stem (C) Pericycle of a dicot stem (D) Ground tissue of a monocot stem\nList II: (1) Semi-lunar patches of sclerenchyma (2) Sclerenchymatous (3) A few layers of collenchyma (4) Parenchyma not differentiated into cortex, endodermis, pericycle and pith", "options": ["A-3, B-2, C-1, D-4", "A-2, B-3, C-4, D-1", "A-2, B-1, C-3, D-4", "A-2, B-3, C-1, D-4"], "answer": 3, "explanation": "The monocot stem has a sclerenchymatous hypodermis and undifferentiated parenchymatous ground tissue with scattered bundles; the dicot stem has a collenchymatous hypodermis and a pericycle of sclerenchyma patches above the phloem.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-56", "question": "Assertion (A): In grasses, the guard cells of stomata are dumb-bell shaped.\nReason (R): In guard cells, the inner walls towards the stomatal pore are thin, while the outer walls away from the pore are highly thickened.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "Grass guard cells are dumb-bell shaped, so A is true. R reverses the wall pattern: the outer walls (away from the pore) are thin and the inner walls (towards the pore) are highly thickened.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-57", "question": "How many of the following statements about the epidermal tissue system are correct?\n(i) The epidermis is covered by a cuticle, which is absent in roots.\n(ii) Root hairs are unicellular elongations of epidermal cells.\n(iii) Trichomes on the stem are usually multicellular.\n(iv) Subsidiary cells are specialised epidermal cells in the vicinity of the guard cells.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Roots lack cuticle, root hairs are unicellular, shoot trichomes are usually multicellular (branched or unbranched), and subsidiary cells surround the guard cells.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-58", "question": "All of the following are features of a typical dicot root EXCEPT:", "options": ["A large, well-developed pith", "The pericycle initiates lateral roots and part of the vascular cambium during secondary growth", "Parenchymatous conjunctive tissue between the xylem and phloem", "Usually two to four xylem and phloem patches"], "answer": 0, "explanation": "In the dicot root the pith is small or inconspicuous; a large, well-developed pith is a monocot root feature.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-morphology-anatomy-59", "question": "Match the stem modification with its example.\nList I: (A) Underground stem storing food (B) Stem tendril (C) Stem thorn (D) Fleshy, cylindrical photosynthetic stem\nList II: (1) Euphorbia (2) Citrus (3) Gourds (4) Zaminkand", "options": ["A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 1, "explanation": "Zaminkand (Amorphophallus) has an underground food-storing stem, gourds climb by stem tendrils from axillary buds, Citrus has stem thorns, and Euphorbia has a fleshy cylindrical green stem.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-60","question":"How many of the following statements about xylem are correct?\n(i) Vessels are a characteristic feature of angiosperms.\n(ii) Xylem fibres have highly thickened walls and obliterated central lumens.\n(iii) Radial conduction of water takes place through the ray parenchymatous cells.\n(iv) Xylem parenchyma cells are living and thin-walled.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: vessels characterise angiosperms, xylem fibres have thick walls and obliterated lumens, ray parenchyma conducts water radially, and xylem parenchyma is the living, thin-walled component of xylem.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-61","question":"Stilt roots, supporting roots that come out of the lower nodes of the stem, are seen in:","options":["Banyan tree branches","Maize and sugarcane","Rhizophora","Carrot and turnip"],"answer":1,"explanation":"Maize and sugarcane have stilt roots from their lower nodes. Banyan has prop roots from its branches, Rhizophora has pneumatophores, and carrot and turnip have storage tap roots.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-62","question":"Fleshy leaves that store food are found in:","options":["Ginger and turmeric","Potato","Onion and garlic","Pea"],"answer":2,"explanation":"The fleshy leaves of onion and garlic store food. Ginger, turmeric and potato store food in underground stems, and pea has leaflets modified into tendrils.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-63","question":"Opposite phyllotaxy, in which a pair of leaves arises at each node, is seen in:","options":["China rose and mustard","Alstonia","Sunflower","Calotropis and guava"],"answer":3,"explanation":"Calotropis and guava have opposite phyllotaxy. China rose, mustard and sunflower have alternate phyllotaxy, and Alstonia has whorled leaves.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-64","question":"In Australian acacia the leaves are small and short-lived. Food is synthesised instead by:","options":["Expanded green petioles","Green thorns on the stem","Leaflets modified into tendrils","Fleshy storage roots"],"answer":0,"explanation":"In Australian acacia the petioles expand, turn green and carry out photosynthesis in place of the small, short-lived leaves.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-65","question":"The gritty texture of the pulp of guava, pear and sapota is due to the presence of:","options":["Collenchyma","Sclereids","Phloem fibres","Aerenchyma"],"answer":1,"explanation":"Sclereids are highly thickened, dead cells with a narrow lumen, found in the pulp of guava, pear and sapota, in the fruit walls of nuts, in the seed coats of legumes and in tea leaves.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-66","question":"Stamens united into more than two bundles (polyadelphous) are found in:","options":["Pea","China rose","Citrus","Brinjal"],"answer":2,"explanation":"Citrus has polyadelphous stamens. China rose has one bundle (monoadelphous), pea has two (diadelphous), and brinjal has epipetalous stamens.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-67","question":"Which of the following seeds is endospermic?","options":["Bean","Chickpea","Pea","Castor"],"answer":3,"explanation":"Castor seeds keep the endosperm as a food store. In bean, gram and pea the endosperm is used up and the food is stored in the cotyledons.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-68","question":"The scar on the seed coat through which the developing seed was attached to the fruit is the:","options":["Micropyle","Hilum","Tegmen","Testa"],"answer":1,"explanation":"The hilum is the attachment scar, and the micropyle is a small pore just above it. Testa and tegmen are the outer and inner layers of the seed coat.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-69","question":"In a dicot stem, the innermost layer of the cortex, whose cells are rich in starch grains, is called the starch sheath. It is the:","options":["Pericycle","Hypodermis","Endodermis","Medullary ray"],"answer":2,"explanation":"In the dicot stem the endodermis is called the starch sheath because its cells are rich in starch grains. The pericycle lies inside it, as semi-lunar patches of sclerenchyma above the phloem.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-70","question":"Monocotyledonous seeds are generally endospermic. An exception, with non-endospermic seeds, is:","options":["Maize","Wheat","Coconut","Orchids"],"answer":3,"explanation":"Most monocot seeds, such as those of maize and wheat, are endospermic, but orchid seeds are non-endospermic.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-71","question":"Colchicine, used in plant breeding, is obtained from Colchicum autumnale, a member of the family:","options":["Liliaceae","Solanaceae","Fabaceae","Poaceae"],"answer":0,"explanation":"Colchicum autumnale belongs to Liliaceae, which also gives ornamentals (tulip, Gloriosa), medicine (Aloe) and vegetables (Asparagus).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-72","question":"In a cymose inflorescence:","options":["The main axis grows indefinitely and flowers are borne in acropetal order","The main axis ends in a flower, and flowers open basipetally","The flowers are always unisexual and sessile","The main axis is absent and all flowers arise from the root"],"answer":1,"explanation":"In cymose inflorescence the main axis ends in a flower and the flowers develop basipetally. In racemose inflorescence the main axis keeps growing and the flowers are borne laterally in acropetal order.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-73","question":"The stomatal apparatus consists of:","options":["Only the stomatal pore, without the guard cells","Guard cells together with the bundle sheath cells beneath them","The aperture, guard cells and surrounding subsidiary cells","Guard cells and the adjoining bulliform cells"],"answer":2,"explanation":"The stomatal aperture, the guard cells and the specialised subsidiary cells around them together make up the stomatal apparatus.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-74","question":"In the transverse section of a monocot stem, the vascular bundles:","options":["Are arranged in a ring, with cambium between xylem and phloem","Are radial, with xylem and phloem on alternate radii","Lie in a ring around a large pith, with exarch xylem","Are scattered, with smaller bundles towards the periphery"],"answer":3,"explanation":"Monocot stem bundles are scattered, conjoint and closed, each with a sclerenchymatous sheath, and the peripheral ones are generally smaller. A ring of open bundles is typical of a dicot stem.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-75","question":"Arrange the regions of a root from the tip upwards.\n(i) Region of elongation (ii) Root cap (iii) Region of maturation (iv) Region of meristematic activity","options":["(ii), (iv), (i), (iii)","(iv), (ii), (i), (iii)","(ii), (i), (iv), (iii)","(ii), (iv), (iii), (i)"],"answer":0,"explanation":"The root cap covers the tip, the meristematic region lies a few millimetres above it, then comes the region of elongation, and then the region of maturation, which bears root hairs.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-76","question":"Which of the following is NOT a lateral (secondary) meristem?","options":["Fascicular vascular cambium","Interfascicular cambium","Cork cambium","Intercalary meristem"],"answer":3,"explanation":"Lateral meristems such as fascicular and interfascicular cambium and cork cambium add secondary tissues. The intercalary meristem lies between mature tissues, for example in grasses, and is a primary meristem.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-77","question":"Match the part of a maize grain with its description.\nList I: (A) Scutellum (B) Coleoptile (C) Coleorhiza (D) Aleurone layer\nList II: (1) Sheath enclosing the radicle (2) Large, shield-shaped cotyledon (3) Proteinous layer separating the endosperm from the embryo (4) Sheath enclosing the plumule","options":["A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-3, B-4, C-1, D-2","A-2, B-4, C-3, D-1"],"answer":1,"explanation":"The scutellum is the single shield-shaped cotyledon, the coleoptile sheathes the plumule, the coleorhiza sheathes the radicle, and the aleurone layer is the proteinous outer layer of the endosperm.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-78","question":"In some leguminous plants, the swollen leaf base is called the:","options":["Stipule","Phyllode","Pulvinus","Ligule"],"answer":2,"explanation":"A swollen leaf base is called the pulvinus. In monocots the leaf base usually forms a sheath, and stipules are small leaf-like outgrowths at the leaf base.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-79","question":"In a dicot stem, the few layers of radially placed parenchyma cells between the vascular bundles form the:","options":["Pericycle","Medullary rays","Conjunctive tissue","Bundle sheath"],"answer":1,"explanation":"Medullary rays are radial bands of parenchyma between the bundles of a dicot stem. Conjunctive tissue is the parenchyma between xylem and phloem in roots.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-80","question":"In the floral formula of Fabaceae, % ⚥ K(5) C1+2+(2) A(9)+1 G1, the part C1+2+(2) indicates:","options":["Five petals, all fused into a single corolla tube","One standard, two lateral wings and two petals fused into a keel","One keel, two standards and two wings, all free from each other","Two whorls of petals, with one petal in the outer whorl"],"answer":1,"explanation":"The papilionaceous corolla has a large posterior standard, two lateral wings, and two anterior petals fused into a keel that encloses the stamens and pistil.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-81","question":"Match the Fabaceae plant with its use.\nList I: (A) Indigofera (B) Sesbania (C) Lupin (D) Muliathi\nList II: (1) Medicine (2) Ornamental (3) Fodder (4) Dye","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-1, B-3, C-2, D-4"],"answer":0,"explanation":"Indigofera gives dye, Sesbania (like Trifolium) is fodder, lupin (like sweet pea) is ornamental, and muliathi is medicinal. Sunhemp, also in Fabaceae, gives fibre.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-82","question":"How many of the following statements about the family Solanaceae are correct?\n(i) The calyx has five free, persistent sepals with valvate aestivation.\n(ii) The five stamens are epipetalous.\n(iii) The ovary is bicarpellary, obliquely placed, syncarpous, superior and unilocular, with parietal placentation.\n(iv) The seeds are non-endospermous.\n(v) The leaves are stipulate.","options":["Only two","Only four","Only one","Only three"],"answer":2,"explanation":"Only (ii) is correct. In Solanaceae the sepals are united, the ovary is bilocular with axile placentation, the seeds are endospermous and the leaves are exstipulate.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-83","question":"How many of the following statements about root hairs and trichomes are correct?\n(i) Root hairs are unicellular elongations of epidermal cells.\n(ii) The trichomes of the shoot system are usually multicellular.\n(iii) Trichomes may be branched or unbranched, and soft or stiff.\n(iv) Trichomes can never be secretory.\n(v) Trichomes help to prevent water loss due to transpiration.","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"Statements (i), (ii), (iii) and (v) are correct. Trichomes may be secretory.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-84","question":"A smoothly cut stump of a temperate tree shows 50 concentric bands, alternating light (spring wood) and dark (autumn wood). Assuming one ring forms each year, how old was the tree?","options":["50 years","100 years","25 years","12 years"],"answer":2,"explanation":"Each annual ring is one light band of spring wood plus one dark band of autumn wood, so 50 bands make 25 annual rings, and the tree was 25 years old.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-85","question":"What is the total number of stamens in a typical flower of Fabaceae, Solanaceae and Liliaceae, respectively?","options":["9, 5 and 3","10, 6 and 6","5, 5 and 6","10, 5 and 6"],"answer":3,"explanation":"Fabaceae has ten diadelphous stamens, (9) + 1, Solanaceae five epipetalous stamens, and Liliaceae six stamens in two whorls, 3 + 3.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-86","question":"Match the plant with its stem modification.\nList I: (A) Pistia (B) Mint (C) Banana (D) Opuntia\nList II: (1) Flattened green stem that photosynthesises (2) Offset with a rosette of leaves and a tuft of roots at each node (3) Slender lateral branch that grows aerially and then arches down to touch the ground (4) Lateral branch that grows horizontally beneath the soil and then comes up obliquely","options":["A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1","A-3, B-2, C-4, D-1","A-2, B-3, C-1, D-4"],"answer":1,"explanation":"Pistia spreads by offsets. Mint and jasmine have slender branches that arch down to the ground, banana, pineapple and Chrysanthemum have underground lateral branches that turn upwards, and Opuntia has a flattened green stem.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-87","question":"From the following list, how many plants have zygomorphic flowers?\nMustard, datura, chilli, pea, gulmohur, bean, Cassia, canna","options":["Three","Four","Five","Six"],"answer":1,"explanation":"Pea, gulmohur, bean and Cassia have zygomorphic flowers. Mustard, datura and chilli are actinomorphic, and canna is asymmetric.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-88","question":"From the following pairs of Solanaceae plant and use, how many are correctly matched?\nChilli: spice; Ashwagandha: medicine; Tobacco: fumigatory; Petunia: ornamental; Belladonna: vegetable; Brinjal: fumigatory","options":["Two","Three","Four","Five"],"answer":2,"explanation":"The first four pairs are correct. Belladonna is a medicinal plant, and brinjal, like tomato and potato, is used as food.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-89","question":"Assertion (A): Cork is impervious to water.\nReason (R): Suberin is deposited in the cell walls of the phellem (cork) cells.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. Cork cells formed by the phellogen are compactly arranged and have suberised walls, which make cork impervious to water; R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-90","question":"Assertion (A): Parenchyma cells are dead at maturity.\nReason (R): Parenchyma cells may be closely packed or may have small intercellular spaces.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"A is false: parenchyma cells are living, thin-walled cells with cellulose walls that carry out photosynthesis, storage and secretion. R is true.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-morphology-anatomy-91","question":"Which feature does NOT belong to the family Fabaceae?","options":["Diadelphous stamens, with nine united and one free","Papilionaceous corolla with descending imbricate (vexillary) aestivation","Bicarpellary, oblique ovary with a swollen axile placenta","Fruit a legume (pod), with non-endospermic seeds"],"answer":2,"explanation":"An obliquely placed bicarpellary ovary with a swollen axile placenta is a Solanaceae feature. Fabaceae has a monocarpellary, unilocular superior ovary with marginal placentation.","difficulty":"hard","source":"NEET"},
  {"id":"bio-plant-morphology-anatomy-92","question":"Which comparison between a typical dicot root and a typical monocot root is INCORRECT?","options":["Xylem bundles: 2 to 4 in the dicot root; usually more than six in the monocot root","Pith: small or inconspicuous in the dicot root; large and well developed in the monocot root","Secondary growth: occurs in the dicot root; does not occur in the monocot root","Casparian strips: present in dicot root endodermis; absent in monocot"],"answer":3,"explanation":"Both kinds of root have an endodermis whose cells carry suberised Casparian strips; this is not a point of difference. The other three rows are the standard differences.","difficulty":"very-hard","source":"NEET"},
  {"id":"bio-plant-morphology-anatomy-93","question":"The periderm formed during secondary growth consists of:","options":["phellogen, phellem and phelloderm","phellem and phellogen only","phellogen, phellem, phelloderm and secondary phloem","phellem, cortex and secondary phloem"],"answer":0,"explanation":"Cork cambium (phellogen) cuts off cork (phellem) to the outside and secondary cortex (phelloderm) to the inside; together the three make up the periderm. Secondary phloem lies inside it and is part of the bark, not the periderm.","difficulty":"moderate","source":"NEET"},
  {"id":"bio-plant-morphology-anatomy-94","question":"How many of the following statements about simple permanent tissues are correct?\n(i) Parenchyma cells have thin cellulose walls and may be closely packed or have small intercellular spaces.\n(ii) Collenchyma cells are thickened at the corners by deposits of cellulose, hemicellulose and pectin.\n(iii) Collenchyma gives mechanical support to growing parts such as young stems and petioles.\n(iv) Sclereids are common in the walls of nuts, the seed coats of legumes and the leaves of tea.\n(v) Sclerenchyma cells are usually living at maturity, with dense protoplasm.\n(vi) Fibres are thick-walled, elongated, pointed cells that generally occur in groups.","options":["4","5","6","3"],"answer":1,"explanation":"Only (v) is wrong: sclerenchyma cells are usually dead and without protoplasm, because of their heavily lignified walls. The remaining five statements are correct.","difficulty":"very-hard","source":"NEET"},
  {"id":"bio-plant-morphology-anatomy-95","question":"Which set consists ONLY of flowers with an inferior ovary (epigynous flowers)?","options":["Guava, cucumber, sunflower ray florets","Plum, rose, peach and cucumber","Mustard, brinjal, China rose and guava","Guava, cucumber, plum and mustard"],"answer":0,"explanation":"In epigynous flowers the thalamus encloses the ovary, which fuses with it, as in guava, cucumber and the ray florets of sunflower. Plum, rose and peach are perigynous (half-inferior ovary), and mustard, brinjal and China rose are hypogynous (superior ovary).","difficulty":"hard","source":"NEET"},
  {"id":"bio-plant-morphology-anatomy-96","question":"How many of the following statements are correct?\n(i) Neem has pinnately compound leaves.\n(ii) Silk cotton has palmately compound leaves.\n(iii) Alstonia shows whorled phyllotaxy.\n(iv) Calotropis shows alternate phyllotaxy.\n(v) In a pinnately compound leaf, the leaflets are attached at a common point at the tip of the petiole.\n(vi) Monocotyledons generally show parallel venation.","options":["5","3","4","6"],"answer":2,"explanation":"Statements (i), (ii), (iii) and (vi) are correct. Calotropis (like guava) has opposite phyllotaxy, and leaflets joined at a common point at the tip of the petiole describe a palmately compound leaf, so (iv) and (v) are false.","difficulty":"very-hard","source":"NEET"},
  {"id":"bio-plant-morphology-anatomy-97","question":"Which statement about mango and coconut, both of which are drupes, is correct?","options":["Mango's edible part is fleshy mesocarp; coconut's mesocarp is fibrous","In mango the stony endocarp is the edible part, whereas in coconut the epicarp is edible","Both develop from multicarpellary, inferior ovaries and contain many seeds","In coconut the fibrous mesocarp is the main edible part"],"answer":0,"explanation":"Drupes develop from monocarpellary superior ovaries and are one-seeded. The pericarp has a thin epicarp, a mesocarp that is fleshy in mango but fibrous in coconut, and a hard, stony endocarp.","difficulty":"hard","source":"NEET"},
  {"id":"bio-plant-morphology-anatomy-98","question":"Which statement about secondary growth in a dicot stem is INCORRECT?","options":["The cambium is more active on its inner side, so more secondary xylem than secondary phloem is formed","The primary and secondary phloem are gradually crushed as secondary xylem keeps accumulating","The primary xylem is crushed, whereas the primary phloem remains more or less intact near the centre","Narrow bands of parenchyma passing radially through the secondary xylem and phloem form secondary medullary rays"],"answer":2,"explanation":"It is the other way round: the primary xylem stays more or less intact in or around the centre, while the phloem outside the cambium is crushed by the growing mass of secondary xylem.","difficulty":"hard","source":"NEET"},
  {"id":"bio-plant-morphology-anatomy-99","question":"Protoxylem lies towards the periphery and metaxylem towards the centre in ____; protoxylem lies towards the pith and metaxylem towards the periphery in ____.","options":["stems (exarch); roots (endarch)","roots (exarch); stems (endarch)","roots (endarch); stems (exarch)","both roots and stems (exarch); leaves (endarch)"],"answer":1,"explanation":"Exarch xylem, with protoxylem facing the periphery, is typical of roots. Endarch xylem, with protoxylem facing the pith, is typical of stems.","difficulty":"moderate","source":"NEET"},
  {"id":"bio-plant-morphology-anatomy-100","question":"Which statement about the stomatal apparatus is correct?","options":["The outer walls of the guard cells, away from the pore, are highly thickened, and the inner walls are thin","Subsidiary cells are present in every plant and contain as many chloroplasts as the guard cells","The stomatal apparatus is made up only of the stomatal pore and the guard cells","In grasses the guard cells are dumb-bell shaped"],"answer":3,"explanation":"Guard cells are usually bean-shaped, but dumb-bell shaped in grasses. Their outer walls are thin and the inner walls next to the pore are thick. The stomatal apparatus includes the pore, the guard cells and the subsidiary cells around them.","difficulty":"hard","source":"NEET"},
  {"id":"bio-plant-morphology-anatomy-101","question":"Roots that arise from parts of the plant other than the radicle are called adventitious roots. NCERT cites them in:","options":["grass, Monstera and banyan tree","mustard, gram and the pea plant","carrot, turnip and the radish","mango, neem and the china rose"],"answer":0,"explanation":"NCERT gives grass, Monstera and the banyan tree as examples of adventitious roots. Mustard, carrot and turnip have tap roots developing from the radicle.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-102","question":"Which statement correctly identifies the organ that has been modified?","options":["Spines of cacti are modified stems, and thorns of Citrus are modified leaves","Thorns of Citrus and Bougainvillea are modified axillary buds of the stem","The phylloclade of Opuntia is a modified leaf, and pea tendrils are stems","Thorns of Bougainvillea are modified roots that protect the plant"],"answer":1,"explanation":"Axillary buds of stems may become woody, straight, pointed thorns, as in Citrus and Bougainvillea. Spines of cacti and tendrils of pea are leaf modifications, while Opuntia's flattened green structure is a stem.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-103","question":"In which plant do more than two leaves arise at a node and form a whorl?","options":["Calotropis","China rose","Alstonia","Guava"],"answer":2,"explanation":"Whorled phyllotaxy is seen in Alstonia. Calotropis and guava show opposite phyllotaxy, and china rose shows alternate phyllotaxy.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-104","question":"Within a single flower, the stamens may differ in the length of their filaments. NCERT cites this in:","options":["pea and bean","lily and onion","china rose and cotton","Salvia and mustard"],"answer":3,"explanation":"NCERT notes that there may be a variation in the length of filaments within a flower, as in Salvia and mustard (mustard has four long and two short stamens).","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-105","question":"How many of the following statements about the family Liliaceae are correct?\n(i) The perianth has six tepals (3 + 3), often united into a tube, with valvate aestivation.\n(ii) The androecium has six stamens (3 + 3) that are epitepalous.\n(iii) The gynoecium is tricarpellary, syncarpous, superior and trilocular with axile placentation.\n(iv) The fruit is a legume and the seeds are non-endospermous.\n(v) Aloe is used as medicine, Asparagus as a vegetable, and tulip and Gloriosa as ornamentals.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i), (ii), (iii) and (v) are correct. The fruit of Liliaceae is a capsule (rarely a berry) and the seeds are endospermous; a legume belongs to Fabaceae.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-106","question":"Intercalary meristems:","options":["occur between mature tissues and, in grasses, regrow parts removed by grazers","occur only at the tips of roots and shoots, where they produce primary tissues","are lateral meristems that increase the girth of the woody stems of trees","are the meristems left behind in leaf axils that later form axillary buds"],"answer":0,"explanation":"Intercalary meristems lie between mature tissues; in grasses they regenerate parts removed by grazing herbivores. Like apical meristems they are primary meristems, unlike the lateral meristems that add girth.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-107","question":"Which statement about xylem parenchyma is correct?","options":["Its cells are dead and lignified, with an obliterated central lumen","It is absent in angiosperms and present only in gymnosperms","It stores starch, fat or tannins; ray cells conduct water radially","It forms the bast fibres used commercially, like jute and hemp"],"answer":2,"explanation":"Xylem parenchyma cells are living and thin-walled; they store food as starch or fat and substances like tannins, and ray parenchyma conducts water radially. Lignified cells with obliterated lumens are xylem fibres, and bast fibres are phloem fibres.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-108","question":"Which statement about phloem fibres (bast fibres) is correct?","options":["They are abundant in primary phloem but absent in secondary phloem","They are living, thin-walled cells that store food as starch","They are linked to sieve tubes by pit fields to maintain pressure","They are generally absent in primary but found in secondary phloem"],"answer":3,"explanation":"Phloem fibres are sclerenchymatous, dead at maturity, generally absent in primary phloem and found in secondary phloem; jute, flax and hemp fibres are commercial examples. Pit-field connections to sieve tubes describe companion cells.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-109","question":"In leaves, the ground tissue consists of:","options":["the mesophyll, with thin-walled green cells","the cuticle, epidermis and stomatal apparatus","the xylem and phloem with their bundle sheath","the pericycle and the medullary rays alone"],"answer":0,"explanation":"All tissues except the epidermis and vascular bundles form the ground tissue; in leaves it is the mesophyll, made of thin-walled cells with chloroplasts.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-110","question":"In a root, the parenchymatous cells lying between the xylem and the phloem are called:","options":["pericycle cells","conjunctive tissue","medullary rays","bundle sheath cells"],"answer":1,"explanation":"In roots, the parenchyma between the radially arranged xylem and phloem is the conjunctive tissue. The pericycle lies just inside the endodermis.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-111","question":"In a transverse section of a young dicot stem, semi-lunar patches of sclerenchyma are seen on the inner side of the endodermis, above the phloem. These belong to the:","options":["hypodermis","cortex","pericycle","bundle sheath"],"answer":2,"explanation":"In a dicot stem the pericycle lies on the inner side of the endodermis and above the phloem, in the form of semi-lunar patches of sclerenchyma. The hypodermis of a dicot stem is collenchymatous.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-112","question":"In a vascular bundle of a dorsiventral leaf, the xylem lies towards the:","options":["abaxial (lower) epidermis","margin of the leaf blade","spongy parenchyma side","adaxial (upper) epidermis"],"answer":3,"explanation":"In the conjoint collateral bundles of a dorsiventral leaf, xylem faces the adaxial (upper) surface and phloem the abaxial (lower) surface, because the leaf trace continues from the stem bundle where xylem is towards the centre.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-113","question":"Lenticels are formed where the phellogen cuts off, on its outer side:","options":["complementary parenchyma cells instead of cork cells","extra layers of suberised cork cells lacking any spaces","secondary phloem elements that are later crushed","phelloderm cells forming the secondary cortex"],"answer":0,"explanation":"At certain regions the phellogen cuts off closely arranged parenchymatous (complementary) cells on the outer side instead of cork cells; these rupture the epidermis to form lens-shaped lenticels that permit gas exchange.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-114","question":"In a dicot stem, much more secondary xylem is formed than secondary phloem because:","options":["the interfascicular cambium produces only xylem towards the pith","the cambium is more active on its inner than its outer side","secondary phloem is converted into xylem after a few years","the cork cambium also adds secondary xylem on its inner side"],"answer":1,"explanation":"The cambial ring is generally more active on the inner side, so more secondary xylem than secondary phloem is produced, and xylem soon forms a compact mass. The cork cambium forms cork and phelloderm, not xylem.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-115","question":"Bark formed early in the season and bark formed towards the end of the season are called, respectively:","options":["hard bark and soft bark","heartwood and sapwood","soft bark and hard bark","spring wood and autumn wood"],"answer":2,"explanation":"NCERT calls bark formed early in the season early or soft bark, and that formed towards the end of the season late or hard bark. Spring and autumn wood are terms for secondary xylem.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-116","question":"Vascular bundles in which xylem and phloem lie on different radii, alternating with each other, are called radial bundles. They are found in:","options":["dicot stems","monocot stems","leaves of grasses","roots"],"answer":3,"explanation":"Radial arrangement of xylem and phloem is typical of roots. Stems and leaves have conjoint bundles, in which xylem and phloem lie on the same radius.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-117","question":"In the family Solanaceae, the gynoecium is:","options":["bicarpellary and obliquely placed, syncarpous, superior, with axile placentation","monocarpellary, superior and unilocular, with many ovules on a marginal placenta","tricarpellary, syncarpous, superior and trilocular, with many ovules on axile placenta","bicarpellary, syncarpous and inferior, with many ovules borne on a parietal placenta"],"answer":0,"explanation":"Solanaceae has a bicarpellary, obliquely placed, syncarpous, superior, bilocular ovary with a swollen placenta bearing many ovules (axile). Monocarpellary marginal is Fabaceae, and tricarpellary trilocular is Liliaceae.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-118","question":"Which family is correctly matched with its fruit and seed type?","options":["Fabaceae — berry or capsule; all seeds endospermous","Liliaceae — capsule (rarely berry); endospermous","Solanaceae — legume pod; seeds non-endospermous","Liliaceae — legume pod; seeds non-endospermous"],"answer":1,"explanation":"Liliaceae has a capsule (rarely a berry) with endospermous seeds; Solanaceae has a berry or capsule with endospermous seeds; Fabaceae has a legume with non-endospermous seeds.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-119","question":"Monadelphous stamens, in which the filaments are united into one bundle, are seen in:","options":["garden pea","citrus","china rose","Gloriosa"],"answer":2,"explanation":"China rose has stamens united into one bunch (monadelphous). Pea is diadelphous, citrus polyadelphous, and Gloriosa (Liliaceae) has free epitepalous stamens.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-120","question":"In mustard and Argemone, the unilocular ovary becomes two-chambered because of:","options":["axile placentation with a true septum between the carpels","free central placentation with ovules on a central axis","basal placentation bearing a single ovule at the base","a false septum, with ovules on parietal placentae"],"answer":3,"explanation":"In parietal placentation the ovules develop on the inner wall of the ovary; in mustard and Argemone the ovary becomes two-chambered due to the formation of a false septum.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-121","question":"Perigynous flowers, in which the ovary is half-inferior, are seen in:","options":["plum, rose and peach","mustard, china rose and brinjal","guava, cucumber and sunflower ray florets","pea, bean and gulmohur"],"answer":0,"explanation":"Plum, rose and peach are perigynous. Mustard, china rose and brinjal are hypogynous (superior ovary), while guava, cucumber and ray florets of sunflower are epigynous (inferior ovary).","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-122","question":"A flower that cannot be divided into two similar halves by any vertical plane passing through its centre is described as asymmetric. An example is:","options":["mustard","canna","pea","datura"],"answer":1,"explanation":"Canna has asymmetric (irregular) flowers. Mustard and datura are actinomorphic, and pea is zygomorphic, divisible into similar halves in only one vertical plane.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-123","question":"Which statement about a dicotyledonous seed is correct?","options":["The outer layer of the seed coat is tegmen and the inner layer is testa","The micropyle is the scar left where the seed was attached to the fruit","The embryo has an axis with two cotyledons, a radicle and a plumule","In gram and pea, the endosperm persists as the main food store of the seed"],"answer":2,"explanation":"The embryo consists of an embryonal axis with two cotyledons, with the radicle and plumule at its ends. The outer seed coat is testa and the inner tegmen, the scar is the hilum, and gram and pea are non-endospermic.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-124","question":"A parthenocarpic fruit is one that:","options":["develops seeds without fertilisation of the egg cell","develops entirely from the thalamus, not from the ovary","ripens from the ovary only after double fertilisation","is formed without fertilisation of the ovary"],"answer":3,"explanation":"NCERT defines a parthenocarpic fruit as one formed without fertilisation of the ovary; such fruits are usually seedless. Seeds forming without fertilisation would be apomixis.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-125","question":"Which statement about the epidermal tissue system is correct?","options":["A waxy cuticle covers the epidermis but is absent in roots","Epidermal cells are dead, sclerenchymatous and closely packed","Trichomes on the stem are usually unicellular and unbranched","Root hairs are multicellular outgrowths of the root epidermis"],"answer":0,"explanation":"The epidermis is covered by a waxy cuticle that prevents water loss, but the cuticle is absent in roots. Epidermal cells are living parenchyma; trichomes are usually multicellular, and root hairs are unicellular.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-126","question":"As secondary growth continues in a dicot stem, which statement is correct?","options":["Primary xylem gets crushed, while primary phloem stays intact at the centre","Primary and secondary phloem get crushed, while primary xylem stays intact","Both the primary xylem and the primary phloem remain fully intact at the centre","Secondary xylem gets crushed by the continued activity of the cork cambium"],"answer":1,"explanation":"Continued accumulation of secondary xylem gradually crushes the primary and secondary phloem, whereas the primary xylem remains more or less intact in or around the centre.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-127","question":"During secondary growth, the cambium forms narrow bands of parenchyma that pass through the secondary xylem and secondary phloem in the radial direction. These are:","options":["conjunctive tissue strands","primary medullary rays","secondary medullary rays","complementary cells of lenticels"],"answer":2,"explanation":"At some places the cambium forms narrow radial bands of parenchyma passing through secondary xylem and phloem; these are the secondary medullary rays. Complementary cells are formed by the phellogen at lenticels.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-128","question":"In a dicot stem, the cork cambium (phellogen) usually develops in the:","options":["pith region","pericycle alone","secondary phloem","cortex region"],"answer":3,"explanation":"As the epidermis ruptures with increasing girth, the phellogen usually develops in the cortex region; it forms cork (phellem) outside and secondary cortex (phelloderm) inside.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-129","question":"Which pair of features distinguishes a monocot stem from a dicot stem?","options":["Sclerenchymatous hypodermis and scattered bundles with a bundle sheath","Collenchymatous hypodermis and bundles arranged in a single ring","A starch sheath and semi-lunar patches of sclerenchyma in pericycle","Conjoint open bundles that are separated by parenchymatous medullary rays"],"answer":0,"explanation":"A monocot stem has a sclerenchymatous hypodermis and many scattered, closed bundles each surrounded by a sclerenchymatous bundle sheath. The other three options describe a dicot stem.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-130","question":"In monocotyledons, the leaf base:","options":["bears two small lateral leaf-like outgrowths called stipules","expands into a sheath covering the stem partly or wholly","is swollen into a pulvinus in all the members","is modified into a tendril that helps in climbing"],"answer":1,"explanation":"NCERT notes that in monocotyledons the leaf base expands into a sheath covering the stem partially or wholly. The pulvinus is the swollen leaf base of some legumes.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-131","question":"In the conjoint vascular bundles of stems and leaves, the phloem is usually located:","options":["on radii alternating with those of the xylem","on the inner side of the xylem, near the pith","only on the outer side of the xylem","in the centre, surrounded by the xylem"],"answer":2,"explanation":"In conjoint bundles xylem and phloem lie on the same radius, and the phloem is usually located only on the outer side of the xylem. Alternate radii describe radial bundles of roots.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-132","question":"During secondary growth in a dicot root, the vascular cambium formed from cells below the phloem and from the pericycle above the protoxylem is initially:","options":["circular, later becoming wavy as the xylem grows","star-shaped, later disappearing completely","a single strip present only below the xylem","wavy, later becoming circular"],"answer":3,"explanation":"Cambium arises from tissue just below the phloem bundles and from the pericycle opposite the protoxylem, forming a complete wavy ring that later becomes circular.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-morphology-anatomy-133","question":"A mature sieve tube element of angiosperm phloem:","options":["has a large central nucleus that also controls the companion cells","has peripheral cytoplasm and a large vacuole but lacks a nucleus","is a dead, lignified cell that lacks cytoplasm, like a xylem vessel","occurs in gymnosperms too, beside albuminous cells and sieve cells"],"answer":1,"explanation":"A mature sieve tube element has peripheral cytoplasm and a large vacuole but no nucleus; its functions are controlled by the nucleus of the companion cell. Gymnosperms have sieve cells and albuminous cells instead of sieve tubes and companion cells.","difficulty":"very-hard","source":"NEET UG"},
];

export default questions;
